using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RegionalCampaignTests
{
    static WorldSession New(params RoadCondition[] changes)=>new(RegionalCampaign.Create(changes));
    static EntityId Start(WorldSession s,EntityId? actor=null){var id="request:move-"+(actor??ContractFixture.Officer).Value.Replace(':','/');Assert.Equal(ResultCode.Accepted,s.Submit(RegionalBranch.Order(s.DiagnosticSnapshot(),id,executor:actor),s.Revision).Code);s.AdvanceTo(Math.Max(5,s.Seconds));return s.DiagnosticSnapshot().Tasks.Last().Id;}
    static string Send(WorldSession s,EntityId target,bool important=false){Assert.Equal(ResultCode.Accepted,s.Submit(RegionalCampaign.Control(s.DiagnosticSnapshot(),"request:cancel",target,ActionKind.Cancel,important),s.Revision).Code);return "message:"+s.DiagnosticSnapshot().Tasks.Last().Id.Value.Replace(':','/')+"/order";}
    [Fact] public void CourierTravelsWaitsAndDeliversAtPhysicalMeeting(){var s=New();Send(s,Start(s));s.AdvanceTo(1000);var w=s.DiagnosticSnapshot();var c=w.Couriers!.Missions.Last();var p=RegionalCampaign.Position(w,c,s.Seconds);Assert.NotEqual(RegionalBranch.Nodes[0].Position,p);Assert.DoesNotContain(s.GetCourierView(ContractFixture.Lord),v=>v.Position!=null);s.AdvanceTo(6000);w=s.DiagnosticSnapshot();Assert.Equal(RegionalBranch.Nodes.Single(n=>n.Id=="fork").Position,RegionalCampaign.Position(w,w.Couriers!.Missions.Single(x=>x.Attempt==c.Attempt),s.Seconds));Assert.DoesNotContain(w.Messaging.Receipts,r=>r.MessageId==w.Messaging.Attempts.Single(a=>a.Id==c.Attempt).MessageId);s.AdvanceTo(11656);Assert.False(s.GetBranchView(ContractFixture.Officer).Walking);}
    [Fact] public void MissReportPhysicallyReturnsBeforeRetryThenNewAddressDeliversOnce(){var s=New();var target=Start(s);s.AdvanceTo(12000);var mid=Send(s,target);s.AdvanceTo(17828);Assert.Equal(ResultCode.NotAvailable,s.RetryCourier(ContractFixture.Lord,mid,"village",20000,s.Revision).Code);s.AdvanceTo(23656);Assert.True(MessageFlow.FailureKnown(s.DiagnosticSnapshot().Messaging,mid+"/attempt/1",ContractFixture.Lord.Value));Assert.Equal(ResultCode.Accepted,s.RetryCourier(ContractFixture.Lord,mid,"village",24000,s.Revision).Code);var due=MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,mid).DueAt;s.AdvanceTo(due);Assert.Single(s.DiagnosticSnapshot().Messaging.Receipts,r=>r.MessageId==mid);Assert.Single(s.DiagnosticSnapshot().EffectLedger,e=>e.BusinessKey=="task:1/finish/1");}
    [Fact] public void DynamicClosureIsUnknownUntilJunctionAndReleaseDoesNotEraseObservation(){var s=New(new RoadCondition(100,"pass",true),new(12000,"pass",false));s=new(RegionalCampaign.Create([new(100,"pass",true),new(12000,"pass",false)],false));Start(s);s.AdvanceTo(1000);Assert.Empty(s.GetBranchView(ContractFixture.Officer).KnownBlockedEdges);s.AdvanceTo(11656);Assert.Contains("pass",s.GetBranchView(ContractFixture.Officer).KnownBlockedEdges);Assert.Empty(s.GetBranchView(ContractFixture.Lord).KnownBlockedEdges);s.AdvanceTo(12001);Assert.Contains("pass",s.GetBranchView(ContractFixture.Officer).KnownBlockedEdges);s.AdvanceTo(20000);ContractValidation.Validate(s.DiagnosticSnapshot());}
    [Theory][InlineData(1000)][InlineData(6000)][InlineData(11656)][InlineData(15000)]
    public void PhysicalCourierSaveAndContinueAgree(long at){var s=New();Send(s,Start(s));s.AdvanceTo(at);var root=Path.Combine(Path.GetTempPath(),"hakutai-campaign-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,RegionalCampaign.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId);var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("test"),host.Current,host.Current.Revision));host.Current.SetPaused(false);s.AdvanceTo(50000);host.Current.AdvanceTo(50000);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Couriers),ContractJson.Write(host.Current.DiagnosticSnapshot().Couriers));Assert.Equal(s.DiagnosticSnapshot().Messaging.Attempts,host.Current.DiagnosticSnapshot().Messaging.Attempts);}
    [Fact] public void TwoOfficersMoveConcurrentlyWithoutRemoteTelemetry(){var s=New();Start(s);Start(s,ContractFixture.Clerk);s.AdvanceTo(15000);Assert.True(s.GetBranchView(ContractFixture.Officer).Walking);Assert.True(s.GetBranchView(ContractFixture.Clerk).Walking);Assert.All(s.GetActorView(ContractFixture.Lord).Tasks,t=>Assert.Equal("発送済・結果未確認",t.KnownStatus));s.AdvanceTo(40000);Assert.Equal(2,s.DiagnosticSnapshot().Tasks.Count(t=>t.Execution==ExecutionPhase.Completed));}

    [Fact] public void RoadReleaseRequiresLocalInspectionAndReportTravel(){var s=New(new RoadCondition(12000,"pass",false));Send(s,Start(s));s.AdvanceTo(12000);Assert.Contains("pass",s.GetBranchView(ContractFixture.Officer).KnownBlockedEdges);Assert.Equal(ResultCode.Accepted,s.InspectRoad(ContractFixture.Officer,"pass",s.Revision).Code);Assert.Empty(s.GetBranchView(ContractFixture.Officer).KnownBlockedEdges);Assert.Empty(s.GetBranchView(ContractFixture.Lord).KnownBlockedEdges);s.AdvanceTo(17484);Assert.Contains("pass",s.GetBranchView(ContractFixture.Lord).KnownBlockedEdges);s.AdvanceTo(17828);Assert.Empty(s.GetBranchView(ContractFixture.Lord).KnownBlockedEdges);}
    [Fact] public void RemoteInspectionCannotRevealTruth(){var s=New();Assert.Equal(ResultCode.NotAvailable,s.InspectRoad(ContractFixture.Lord,"pass",s.Revision).Code);Assert.Empty(s.GetBranchView(ContractFixture.Lord).KnownBlockedEdges);}
    [Fact] public void ClosureInsideAnEdgeDoesNotTeleportAnOfficerOrCourier(){var s=New(new RoadCondition(100,"road",true));Send(s,Start(s));s.AdvanceTo(11656);Assert.Equal(RegionalCampaign.Nodes.Single(n=>n.Id=="fork").Position,s.GetBranchView(ContractFixture.Officer).Position);Assert.False(s.GetBranchView(ContractFixture.Officer).Walking);}
    [Fact] public void FullDisconnectionStopsAtTheReachedJunctionWithoutCrashingReports(){var s=New(new RoadCondition(100,"road",true),new(100,"kasadera-access",true));Start(s);s.AdvanceTo(50000);Assert.False(s.GetBranchView(ContractFixture.Officer).Walking);Assert.Equal(RegionalCampaign.Nodes.Single(n=>n.Id=="fork").Position,s.GetBranchView(ContractFixture.Officer).Position);Assert.All(s.GetActorView(ContractFixture.Lord).Tasks,t=>Assert.Equal("発送済・結果未確認",t.KnownStatus));}
    [Theory][InlineData("inabayama")][InlineData("okazaki")]
    public void AdjacentRegionMovementAndPhysicalReturnReport(string destination){var s=New();var i=RegionalCampaign.Move(s.DiagnosticSnapshot(),"request:region",destination);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);s.AdvanceTo(11+i.WorkSeconds);Assert.Equal(RegionalCampaign.Site(destination),s.GetActorView(ContractFixture.Officer).Location.Site);Assert.Equal("発送済・結果未確認",s.GetActorView(ContractFixture.Lord).Tasks.Single().KnownStatus);var report=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="contract-report");var due=MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,report.Id).DueAt;Assert.True(due>s.Seconds);s.AdvanceTo(due);Assert.Equal("任務完了",s.GetActorView(ContractFixture.Lord).Tasks.Single().KnownStatus);}
    [Fact] public void SenderCannotObserveRemoteFailureThroughCourierList(){var s=New();var target=Start(s);s.AdvanceTo(12000);Send(s,target);s.AdvanceTo(16000);var before=s.GetCourierView(ContractFixture.Lord).Where(c=>c.Message=="message:task/2/order").ToArray();s.AdvanceTo(18000);Assert.Equal(before.Select(c=>c with{Position=null}),s.GetCourierView(ContractFixture.Lord).Where(c=>c.Message=="message:task/2/order").Select(c=>c with{Position=null}));}
    [Fact] public void TamperedCourierPositionAndConditionHistoryAreRejected(){var s=New();Send(s,Start(s));var w=s.DiagnosticSnapshot();var c=w.Couriers!.Missions.Last();w.Couriers=w.Couriers with{Missions=w.Couriers.Missions.Select(x=>x==c?x with{Origin=new(1,2)}:x).ToArray()};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Branches=w.Branches! with{BlockedEdges=[]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact] public void OldWorldDoesNotSilentlyAcquireNewCourierRules(){var old=RegionalControl.Create();Assert.Null(ContractJson.Copy(old).Couriers);Assert.Equal(RegionalControl.Ruleset,new WorldSession(old).DiagnosticSnapshot().Definitions.Ruleset);}
    [Fact] public void ConcurrentOfficersShareOneClockAndFinishWithoutDuplicateEffects(){var w=RegionalCampaign.Create();for(int n=0;n<16;n++){var id=new EntityId("person:load-"+n);w.Definitions=w.Definitions with{Characters=[..w.Definitions.Characters,new(id,"負荷検証武将") ]};w.Characters=[..w.Characters,new(id,LifeState.Adult,new("appearance:fixture"),0)];w.Grants=[..w.Grants,w.Grants[0] with{Id=new("grant:load-"+n),Agent=id}];w.Locations=[..w.Locations,new(id,LocationKind.AtSite,ContractFixture.Castle,null,0,0,null,null,null,null,0)];}var s=new WorldSession(w);foreach(var actor in w.Characters.Where(c=>c.Id!=ContractFixture.Lord)){var order=RegionalCampaign.Move(s.DiagnosticSnapshot(),"request:load-"+actor.Id.Value.Replace(':','/'),"village",actor.Id);Assert.Equal(ResultCode.Accepted,s.Submit(order,s.Revision).Code);}s.AdvanceTo(12000);var folder=Path.Combine(Path.GetTempPath(),"hakutai-multi-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(folder,w.Definitions);store.Save(s,"many",w.WorldId);var host=new WorldSessionHost(new WorldSession(w));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("many"),host.Current,host.Current.Revision));host.Current.SetPaused(false);host.Current.AdvanceTo(50000);s.AdvanceTo(50000);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Branches),ContractJson.Write(host.Current.DiagnosticSnapshot().Branches));Assert.Equal(s.DiagnosticSnapshot().Messaging.Attempts,host.Current.DiagnosticSnapshot().Messaging.Attempts);Assert.Equal(18,s.DiagnosticSnapshot().Tasks.Count(t=>t.Execution==ExecutionPhase.Completed));Assert.Equal(18,s.DiagnosticSnapshot().EffectLedger.Count(e=>e.BusinessKey.EndsWith("/finish/1")));ContractValidation.Validate(s.DiagnosticSnapshot());}

    [Fact] public void DistantObserverViewDoesNotDependOnUnseenClosure(){var a=new WorldSession(RegionalCampaign.Create(initiallyBlocked:false));var b=new WorldSession(RegionalCampaign.Create());Start(a);Start(b);a.AdvanceTo(10000);b.AdvanceTo(10000);Assert.Equal(ContractJson.Write(a.GetActorView(ContractFixture.Lord)),ContractJson.Write(b.GetActorView(ContractFixture.Lord)));Assert.Equal(ContractJson.Write(a.GetCourierView(ContractFixture.Lord)),ContractJson.Write(b.GetCourierView(ContractFixture.Lord)));Assert.Equal(ContractJson.Write(a.GetBranchView(ContractFixture.Officer)),ContractJson.Write(b.GetBranchView(ContractFixture.Officer)));}
    [Fact] public void PhysicalLateArrivalCannotBeInjectedWithOnlyATimer(){var s=New();var target=Start(s);s.AdvanceTo(12000);var mid=Send(s,target);s.AdvanceTo(24000);Assert.Throws<InvalidDataException>(()=>s.DiagnosticTransport((m,t)=>MessageFlow.ScheduleLate(m,mid,1,t,1)));}
    [Fact] public void RetryRejectsUnknownAddressAndStaleRevision(){var s=New();var target=Start(s);s.AdvanceTo(12000);var mid=Send(s,target);s.AdvanceTo(24000);Assert.Equal(ResultCode.StateChanged,s.RetryCourier(ContractFixture.Lord,mid,"village",24000,s.Revision-1).Code);Assert.Equal(ResultCode.NotAvailable,s.RetryCourier(ContractFixture.Lord,mid,"secret-location",24000,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().Messaging.Attempts,a=>a.MessageId==mid);}

    [Theory][InlineData("inabayama")][InlineData("okazaki")]
    public void ControlAddressComesFromKnownOriginalMission(string destination){var s=New();s.Submit(RegionalCampaign.Move(s.DiagnosticSnapshot(),"request:regional",destination),s.Revision);s.AdvanceTo(5);var task=s.DiagnosticSnapshot().Tasks.Single();var i=RegionalCampaign.Control(s.DiagnosticSnapshot(),"request:regional-control",task.Id,ActionKind.Cancel,false);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);s.AdvanceTo(100000);Assert.Equal(ExecutionPhase.Stopped,s.DiagnosticSnapshot().Tasks.Single(t=>t.Id==task.Id).Execution);}
}
